package com.cryptopulse.app;
import android.app.*;import android.content.*;
public class BootReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){if(!Store.yes(c,"enabled",false))return;if(Store.yes(c,"resumeBoot",true)){try{c.startForegroundService(new Intent(c,MonitorService.class).setAction("START"));return;}catch(Exception e){Store.log(c,"Automatic resume blocked: "+e.getMessage());}}if(!Store.yes(c,"bootReminder",true))return;NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("monitor","Background monitoring",NotificationManager.IMPORTANCE_LOW));nm.notify(2,new Notification.Builder(c,"monitor").setSmallIcon(c.getResources().getIdentifier("notification_icon","drawable",c.getPackageName())).setContentTitle("Resume CryptoPulse Audio").setContentText("Phone restarted. Open the app and tap Start to resume your voice alerts.").setContentIntent(PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).setAutoCancel(true).build());}}
